 const admin=await users.createUser({username:'reply-admin-'+randomUUID().slice(0,8),email:randomUUID()+'@example.invalid',passwordHash});await migration.query("UPDATE identity.users SET role='super_admin',admin_level=2,email_verified=1 WHERE id=$1",[admin.id]);for(const permission of ['user_management','challenge_management','system_config','manage_progress','system_logs','view_analytics'])await users.grantPermission({userId:admin.id,permission,grantedBy:admin.id});
 await config.setMasterHintVisibility(key,true);await config.setMasterSolutionVisibility(key,true);await config.setObjectiveHintVisibility(key,id,true);await config.setObjectiveSolutionVisibility(key,id,true);
