 const fixtures=require('../../server/services/secureshopPersonaInboxComposition').mapPersonaInboxFixtures(templates),mail=require('../../server/database/postgres/secureshopBoundMailRepository').createBoundMailRepository({pool:agents,personaAuthority:authority,checkCleanup:input=>cleanupAuthority.checkTarget({...input,targetKind:'persona_inbox',fromGeneration:input.generation})});
 const reader=require('../../server/database/postgres/secureshopMailEvidenceRepository').createMailEvidenceRepository({personaAuthority:authority,mailRepository:mail}),progress=require('../../server/database/postgres/workshopProgressRepository').createWorkshopProgressRepository(identity),scopeOf=require('../../server/services/secureshopConversationBinding').createLaunchScope;
 const immutable=async owner=>(await identity.query('SELECT j.*,p.packet FROM workshop_platform.objective_judgments j JOIN workshop_platform.grade_packets p USING(user_id,evaluation_id) WHERE j.user_id=$1 ORDER BY j.evaluation_id',[owner])).rows;
 async function sourceFor(scope,subject,body){const target=await launches.reservePersonaInboxTarget({...scope,expectedGeneration:scope.generation});await bundle.repository.provision({...scope,targetId:target.targetId},{fixtures,mode:'advisory'});const customer=await require('./secureshopMailQualificationContracts').authenticateMailPersona({auth,scope,templates,role:'customer'});const binding={...customer,targetId:target.targetId,mode:'vuln',operationId:randomUUID()},payload=require('./secureshopMailQualificationContracts').mailSourceEnvelope({templates,context:binding,recipientRole:'merchant',subject,body_markdown:body});return{binding,payload,sent:await mail.send(binding,payload)};}
 const siblingScope=scopeOf(siblingBinding),siblingSource=await sourceFor(siblingScope,'Sibling preserved mail','Owned unrelated sibling baseline');const siblingRows=async()=>await auditRead(siblingSource.binding.targetId),siblingBefore=await siblingRows();assert(siblingBefore.length>0);
